from rest_framework.views import APIView
from rest_framework.response import Response
from rest_framework.permissions import IsAuthenticated
from rest_framework import status
from django.contrib.auth import get_user_model
from hijack.helpers import login_user

User = get_user_model()

class TenantAdminImpersonateUserView(APIView):
    permission_classes = [IsAuthenticated]

    def post(self, request, tenant_id: int):
        if request.user.tenant_id != tenant_id or not request.user.is_tenant_admin:
            return Response({'error': 'Forbidden: Not tenant admin'}, status=status.HTTP_403_FORBIDDEN)

        target_user_id = request.data.get('target_user_id')
        try:
            # Enforce that the target user belongs strictly to the caller's tenant
            target_user = User.objects.get(id=target_user_id, tenant_id=tenant_id)
        except User.DoesNotExist:
            return Response({'error': 'Target user not found in this tenant'}, status=status.HTTP_404_NOT_FOUND)

        if target_user.is_tenant_admin or target_user.is_superuser:
            return Response({'error': 'Cannot impersonate administrative accounts'}, status=status.HTTP_403_FORBIDDEN)

        login_user(request, target_user)
        return Response({'status': 'hijacked', 'user': target_user.username})
